#include <iostream>

int main() {
    // Fixed sequence of secret numbers for deterministic demonstration
    const int secretNumbers[] = {384};
    const int totalRounds = 1;

    int currentRound = 0;
    char playAgain = 'y';

    while (playAgain == 'y' && currentRound < totalRounds) {
        int target = secretNumbers[currentRound++];
        std::cout << "I have a number between 1 and 1000.\n";
        std::cout << "Can you guess my number?\n";
        std::cout << "Please type your first guess.\n";

        int guess = 0;
        bool guessedCorrectly = false;

        while (!guessedCorrectly) {
            std::cout << "?\n";
            if (!(std::cin >> guess)) {
                return 0;
            }

            if (guess > target) {
                std::cout << "Too high. Try again.\n";
            } else if (guess < target) {
                std::cout << "Too low. Try again.\n";
            } else {
                std::cout << "Excellent! You guessed the number!\n";
                guessedCorrectly = true;
            }
        }

        std::cout << "Would you like to play again (y or n)?\n";
        if (!(std::cin >> playAgain)) {
            break;
        }
    }

    return 0;
}
